CHAINS=[{'chain': '600678-收到部分款项后，履约风险是否真的下降？', 'source': '1225597901', 'pages': [2], 'subject': '收到部分款项后，履约风险是否真的下降？', 'changed': '首笔收到后，7月30日第二笔本金和利息未按期支付，公司提交强制执行申请。9月30日又收本金和利息合计100万元。应更新为部分回收与违约并存，不是按期全部履行。', 'open': '核执行受理与实际后续回款，分别记录本金、利息和现金时点。二审审结不是全部执行完毕。', 'boundary': '发生、披露与现金/报表期间分别看；日期对齐行情不识别公告净影响。', 'supporting': [{'source': '1225450529', 'pages': [2], 'state': '仅已核原页，不认证全文。'}]}, {'chain': '600678-三笔专项检查，是否证明内控审计问题已消除？', 'source': '1225448756', 'pages': [14, 15], 'subject': '三笔专项检查，是否证明内控审计问题已消除？', 'changed': '顺宇1500万元已收回；顺宏剩余615.32万元以银行承兑汇票背书偿还；中辉专项报告记载尚余1770万元本金。报告仅针对三笔预付款合规性，限独立董事履职、内部核查及监管备查，不是年度内控消除结论。', 'open': '核年度审计独立结论，不把承兑汇票当现金，不把其他子公司已收回款当中辉已全部收回，也不把7月出具报告倒填7月3日已知。', 'boundary': '发生、披露与现金/报表期间分别看；日期对齐行情不识别公告净影响。', 'supporting': []}, {'chain': '600734-亏损收窄、现金转正，收入也改善了吗？', 'source': '1225637504', 'pages': [2], 'subject': '亏损收窄、现金转正，收入也改善了吗？', 'changed': '半年营收比较期因同控合并追溯调整，改为157106646.62元。第三季度归母亏损13804864.52元，前三季亏损42173381.13元；前三季经营现金10775074.23元转正，但收入按重述比较期下降22.75%。改善方向不一致。', 'open': '核实际年度扣除后收入、利润与审计条件；同比用调整后比较期，原报保留。单季现金由累计减半年另算。', 'boundary': '发生、披露与现金/报表期间分别看；日期对齐行情不识别公告净影响。', 'supporting': [{'source': '1225515124', 'pages': [5], 'state': '仅已核原页，不认证全文。'}, {'source': '1225515109', 'pages': [2], 'state': '仅已核原页，不认证全文。'}]}, {'chain': '600735-占款警示已撤销，剩余内控待办关闭了吗？', 'source': '1225669762', 'pages': [1], 'subject': '占款警示已撤销，剩余内控待办关闭了吗？', 'changed': '11月13日进展仍引用2025年度内控否定意见。占款问题4月20日解决、对应警示获撤销，与剩余内控警示分列；治理制度与检查措施属于推进，不是新审计验证。第三季度扣非转正，但前三季收入、归母与扣非仍同比下降。', 'open': '核内控独立验证、调查及合并范围变化，不从资金占用清偿直接推断全部经营或警示修复。', 'boundary': '发生、披露与现金/报表期间分别看；日期对齐行情不识别公告净影响。', 'supporting': [{'source': '1225523413', 'pages': [6], 'state': '仅已核原页，不认证全文。'}, {'source': '1225650591', 'pages': [1], 'state': '仅已核原页，不认证全文。'}]}, {'chain': '600735-重整延期，究竟改变了谁的时间表？', 'source': '1225650603', 'pages': [1], 'subject': '重整延期，究竟改变了谁的时间表？', 'changed': '控股与间接控股股东等22家公司重整计划草案提交期限延至2027年1月10日。当前是股东集团计划待提交，不是上市公司自身重整获批，也不能直接确认控制权已变更。', 'open': '核计划提交、法院批准、股权实施与控制权实际变化；不将集团程序进展替代上市公司内控整改。', 'boundary': '发生、披露与现金/报表期间分别看；日期对齐行情不识别公告净影响。', 'supporting': []}, {'chain': '600745-系统运行改善，审计事项和经营已恢复了吗？', 'source': '1225648279', 'pages': [2], 'subject': '系统运行改善，审计事项和经营已恢复了吗？', 'changed': '10月31日披露新SAP运行与客户EDI搭建，但同时明确谈判无实质进展、未达成安排，无法表示意见所涉事项尚未消除。前三季归母亏损622759135.17元、经营现金净流出495083600.33元；业务剥离及境外控制权受限改变规模，不能按同一业务简单比较收入。', 'open': '核独立审计验证、控制权及历史数据证据，继续看亏损与现金；系统恢复不自动补足2025年度取证。', 'boundary': '发生、披露与现金/报表期间分别看；日期对齐行情不识别公告净影响。', 'supporting': [{'source': '1225474432', 'pages': [7], 'state': '仅已核原页，不认证全文。'}, {'source': '1225620733', 'pages': [1, 2], 'state': '仅已核原页，不认证全文。'}]}]
